class IdentifyCommitteeModule(dspy.Module):
    def __init__(self):
        super().__init__()
        # The LM is ONLY a fallback for emails whose sponsor cannot be recovered
        # deterministically (or where the deterministic guess is low-confidence).
        self.fallback = dspy.Predict(dspy.Signature(
            "email_body: str -> committee: str",
            "You are given the full text of a political fundraising email whose sponsoring "
            "committee could NOT be recovered by deterministic parsing. Return the legal name of "
            "the political committee that paid for the email, copied verbatim from the email text.\n\n"
            "Where to look, in priority order:\n"
            "1. The FEC disclaimer, usually near the bottom. It appears in forms such as "
            "'Paid for by <COMMITTEE>', 'Paid for and authorized by <COMMITTEE>', 'Paid political "
            "advertisement paid for and provided in kind by <COMMITTEE>', or 'Authorized by "
            "<COMMITTEE>'. The committee name is everything after 'by' up to the first comma, "
            "semicolon, sentence-ending period, pipe, treasurer/officer name, mailing address "
            "(e.g. 'P.O. Box', a street number), or the start of the next sentence (such as 'not "
            "authorized by any candidate...', \"Don't want to receive...\", 'Click here to "
            "unsubscribe...').\n"
            "2. 'Checks can be made payable to <COMMITTEE>' or 'Contributions to <COMMITTEE> are "
            "not deductible...'.\n"
            "3. The organization named in the footer address block (the capitalized name directly "
            "before a P.O. Box or street address), or the sending organization in the header.\n\n"
            "Domain knowledge and rules:\n"
            "- Plain-text conversion of these emails frequently DELETES spaces, gluing words "
            "together (e.g. 'theNRSC', 'ofAmerica', 'SouthCarolina'). Restore the intended word "
            "boundaries and drop a glued leading article like 'the' if it is not part of the name.\n"
            "- Committee names routinely contain middle initials with periods (e.g. 'First M. Last "
            "for <State>'); KEEP those initials and their periods — never truncate the name at an "
            "initial.\n"
            "- Names often end in words like Committee, Campaign, Fund, PAC, Inc., Victory, Action, "
            "Friends of, or 'for <State/Office>'. Include the whole phrase.\n"
            "- Some committees are referred to only by their well-known acronym in the disclaimer "
            "(all-capital letters). In that case return that acronym exactly as written, with no "
            "surrounding article and no trailing period.\n"
            "- The name is frequently written twice in a row just before the mailing address. "
            "Report the name ONCE, with words correctly separated.\n"
            "- Output ONLY the committee name: no 'Paid for by' prefix, no treasurer or officer "
            "name, no street address, no trailing punctuation, no explanation.\n"
            "- Preserve the email's own spelling and capitalization. Keep a leading 'The' only if "
            "the email capitalizes it as part of the name.\n"
            "- Never substitute a candidate's personal name alone, a slogan, a vendor (ActBlue, "
            "NGP VAN, ActionNetwork), or a URL when the committee name appears in the email.\n"
            "- If several disclaimers appear, use the one that paid for THIS email."
        ))

    def forward(self, **inputs):
        import re

        text = inputs.get("email_body") or ""
        if not isinstance(text, str):
            text = str(text)

        FUNCTION_WORDS = {
            "for", "of", "the", "and", "a", "an", "to", "de", "del", "la", "el",
            "en", "y", "&", "por", "van", "on", "at",
        }
        STOP_WORDS = {
            "don't", "don’t", "dont", "do", "does", "doesn't", "not", "if", "click",
            "unsubscribe", "this", "these", "that", "those", "contributions",
            "contribution", "paid", "view", "text", "copyright", "all", "rights",
            "privacy", "policy", "we", "you", "your", "our", "us", "want", "wants",
            "please", "email", "emails", "address", "po", "p.o", "box", "suite",
            "sent", "authorized", "checks", "check", "receive", "received",
            "receiving", "having", "trouble", "forward", "made", "payable", "was",
            "is", "are", "am", "be", "he", "she", "they", "it", "but", "because",
            "so", "then", "no", "yes", "stop", "reply", "msg", "message", "here",
            "learn", "more", "about", "update", "prefer", "would", "will", "can",
            "may", "help", "donate", "donation", "contribute", "chip", "in",
            "with", "from", "by", "or", "who", "which", "when", "what",
            "why", "how", "hate", "see", "go", "going", "still", "like",
            "united states", "http", "https", "www",
        }
        ABBREV = {
            "inc", "corp", "co", "ltd", "llc", "jr", "sr", "st", "mt", "dept",
            "natl", "assn", "cmte",
        }
        KEYWORDS = {
            "committee", "cmte", "pac", "fund", "campaign", "friends", "victory",
            "action", "for", "inc", "llc", "party", "alliance", "project",
            "americans", "america", "citizens", "council", "network", "group",
            "coalition", "leadership", "majority", "senate", "congress",
            "congressional", "district", "elect", "reelect", "committees",
        }
        HARD_END = (",", ";", ":", "!", "?", "|")

        def normalize(s: str) -> str:
            """Collapse whitespace / invisible chars so the text scans as one line."""
            s = s.replace("\u00a0", " ").replace("\u200b", " ").replace("\u034f", " ")
            s = s.replace("͏", " ")
            return re.sub(r"\s+", " ", s).strip()

        def unglue(s: str) -> str:
            """Re-insert the space that plain-text conversion dropped between a
            lowercase function word and a following capitalized word, e.g.
            'theNRSC' -> 'the NRSC', 'ofAmerica' -> 'of America'.

            Only leading function words are split, so genuine mixed-case names
            (e.g. an acronym embedded in a name) are left untouched."""
            return re.sub(
                r"\b(the|The|and|of|for|to|by|in|at|our|my|your)(?=[A-Z][A-Za-z])",
                r"\1 ",
                s,
            )

        def clean_token(tok: str) -> str:
            """Strip surrounding quotes/brackets/dashes/stars from a whitespace token."""
            return tok.strip(" \t\"'“”‘’()[]{}<>*|—–_-")

        def alnum(s: str) -> str:
            """Lowercased alphanumeric-only projection of a string."""
            return re.sub(r"[^a-z0-9]", "", s.lower())

        def is_initialism(tok: str) -> bool:
            """True for tokens like 'B.', 'U.S.', 'D.C.' (letter-dot sequences)."""
            return bool(re.fullmatch(r"(?:[A-Za-z]\.){1,4}", tok))

        def dedupe(tokens: list) -> list:
            """If the token run is the same name repeated 2-3 times (possibly with
            words glued together by line wrapping), keep the best-separated copy."""
            s = "".join(alnum(t) for t in tokens)
            n = len(s)
            if n < 6:
                return tokens
            for reps in (2, 3):
                if n % reps:
                    continue
                unit = n // reps
                if s != s[:unit] * reps:
                    continue
                blocks, cur, acc = [], [], 0
                ok = True
                for t in tokens:
                    cur.append(t)
                    acc += len(alnum(t))
                    if acc == unit:
                        blocks.append(cur)
                        cur, acc = [], 0
                    elif acc > unit:
                        ok = False
                        break
                if not ok or cur or len(blocks) < 2:
                    continue
                if all("".join(alnum(t) for t in b) == s[:unit] for b in blocks):
                    return max(blocks, key=lambda b: len(b))
            return tokens

        def extract_name(tail: str) -> str:
            """Extract a committee name from the text right after a disclaimer phrase."""
            tail = unglue(normalize(tail)).lstrip(":,-–—* ")
            out = []
            for raw in tail.split(" ")[:24]:
                tok = clean_token(raw)
                if not tok:
                    break
                stripped = tok.rstrip("\"'“”‘’)]}")
                core = stripped.rstrip(".,;:!?")
                if not core:
                    break
                low = core.lower()
                if any(ch.isdigit() for ch in core):
                    break
                if low in STOP_WORDS:
                    break
                if low.endswith("'t") or low.endswith("’t"):
                    break
                if core[0].islower() and low not in FUNCTION_WORDS:
                    break
                initial_like = is_initialism(stripped) or (len(core) == 1 and core.isalpha())
                piece = core
                if stripped.endswith(".") and (initial_like or low in ABBREV):
                    piece = core + "."
                out.append(piece)
                if stripped.endswith(HARD_END):
                    break
                if stripped.endswith("."):
                    # A period ends the name UNLESS it is an initial or a known
                    # abbreviation (e.g. a middle initial, 'Inc.').
                    if not (initial_like or low in ABBREV):
                        break
            while out and out[-1].rstrip(".").lower() in FUNCTION_WORDS:
                out.pop()
            while out and out[0].lower() in FUNCTION_WORDS and out[0].lower() != "the":
                out.pop(0)
            out = dedupe(out)
            return " ".join(out).strip()

        def looks_valid(name: str) -> bool:
            """Basic shape check: a few tokens, at least one capitalized word."""
            if not name or len(name) < 3:
                return False
            toks = name.split()
            if not (1 <= len(toks) <= 14):
                return False
            return any(t[:1].isupper() for t in toks)

        def core_tokens(name: str) -> list:
            """Tokens of the name ignoring a leading article."""
            toks = name.split()
            if toks and toks[0].lower() == "the":
                toks = toks[1:]
            return toks

        def is_confident(name: str) -> bool:
            """Reject guesses that look truncated or too thin to be a legal name."""
            if not looks_valid(name):
                return False
            toks = core_tokens(name)
            if not toks:
                return False
            last = toks[-1].rstrip(".")
            if len(last) <= 1:
                return False  # truncated at a middle initial, e.g. 'First M'
            if len(toks) == 1:
                # A lone token is only trusted as an acronym (e.g. an all-caps
                # committee abbreviation), never as a bare personal name.
                bare = toks[0].rstrip(".")
                if bare.isupper() and 2 <= len(bare) <= 8:
                    return True
                # 'N.R.S.C.'-style dotted acronyms are also fine.
                if is_initialism(toks[0]) and len(alnum(toks[0])) >= 2:
                    return True
                return False
            if len(toks) == 2 and not any(
                t.lower().rstrip(".") in KEYWORDS for t in toks
            ):
                # Two capitalized words with no committee-ish word is usually just
                # a person's name -> low confidence.
                if all(t[:1].isupper() and t[1:].islower() for t in toks):
                    return False
            return True

        def has_keyword(name: str) -> bool:
            """Whether the name contains a word typical of committee legal names."""
            return any(t.lower().rstrip(".,") in KEYWORDS for t in name.split())

        def fix_leading_the(name: str, source: str) -> str:
            """Keep a leading 'The' only if the email capitalizes it as part of the name."""
            if name.lower().startswith("the "):
                rest = name[4:].strip()
                if not rest:
                    return name
                if re.search(r"\bThe\s+" + re.escape(rest), source):
                    return "The " + rest
                return rest
            return name

        def name_before(idx: int) -> str:
            """Read a capitalized organization name ending just before position idx
            (used for the footer '<Committee> PO Box ...' address block)."""
            seg = unglue(normalize(norm[max(0, idx - 220):idx]))
            toks = [clean_token(t) for t in seg.split(" ")]
            toks = [t for t in toks if t]
            coll = []
            for t in reversed(toks):
                stripped = t.rstrip("\"'“”‘’)]}")
                core = stripped.rstrip(".,;:!?")
                if not core:
                    break
                low = core.lower()
                if any(ch.isdigit() for ch in core):
                    break
                if low in STOP_WORDS:
                    break
                if core[0].islower() and low not in FUNCTION_WORDS:
                    break
                piece = core
                if stripped.endswith(".") and (
                    is_initialism(stripped) or len(core) == 1 or low in ABBREV
                ):
                    piece = core + "."
                coll.append(piece)
                if len(coll) >= 12:
                    break
            coll.reverse()
            while coll and coll[0].lower() in FUNCTION_WORDS and coll[0].lower() != "the":
                coll.pop(0)
            while coll and coll[-1].rstrip(".").lower() in FUNCTION_WORDS:
                coll.pop()
            coll = dedupe(coll)
            return " ".join(coll).strip()

        def vote(cands: list) -> str:
            """Pick the most frequent candidate, breaking ties by first appearance."""
            counts, order = {}, {}
            for i, c in enumerate(cands):
                key = c.lower()
                counts[key] = counts.get(key, 0) + 1
                if key not in order:
                    order[key] = (i, c)
            if not counts:
                return ""
            best_key = max(counts, key=lambda k: (counts[k], -order[k][0]))
            return order[best_key][1]

        norm = normalize(text)

        # Tiered disclaimer patterns, strongest first.
        patterns = [
            r"paid\s+for\s+(?:and\s+(?:\w+\s+){0,5})?by\b",
            r"paid\s+(?:political\s+)?(?:advertisement\s+)?(?:and\s+)?(?:provided\s+in\s+kind\s+)?by\b",
            r"authorized\s+(?:and\s+paid\s+for\s+)?by\b",
            r"checks?\s*(?:can|should)?\s*(?:be)?\s*made\s*payable\s*to\b",
            r"make\s*checks?\s*payable\s*to\b",
            r"contributions?\s*(?:to|for)\b",
        ]

        tiers = []
        for pat in patterns:
            cands = []
            for m in re.finditer(pat, norm, flags=re.IGNORECASE):
                cand = extract_name(norm[m.end(): m.end() + 320])
                if looks_valid(cand):
                    cands.append(cand)
            if cands:
                tiers.append(cands)
                if any(is_confident(c) for c in cands):
                    break  # strongest tier with a trustworthy name wins

        chosen = ""
        for cands in tiers:
            conf = [c for c in cands if is_confident(c)]
            if conf:
                chosen = vote(conf)
                break
        if not chosen and tiers:
            chosen = vote(tiers[0])

        if is_confident(chosen):
            chosen = fix_leading_the(chosen, norm)
            return dspy.Prediction(committee=str(chosen).strip(" .,;:|"))

        # Second deterministic strategy: the footer address block, e.g.
        # "<Committee Name>, PO Box 123, City, ST 00000" or "<Name> 123 Main St".
        addr_pats = [
            r"P\.?\s?O\.?\s+Box\b",
            r"\b\d{2,6}\s+[A-Z][A-Za-z]+\s+(?:St\b|Street\b|Ave\b|Avenue\b|Rd\b|Road\b|"
            r"Blvd\b|Boulevard\b|Dr\b|Drive\b|Ln\b|Lane\b|Way\b|Pl\b|Place\b|Suite\b|Ste\b)",
        ]
        for pat in addr_pats:
            for m in re.finditer(pat, norm):
                cand = name_before(m.start())
                if is_confident(cand) and has_keyword(cand):
                    cand = fix_leading_the(cand, norm)
                    return dspy.Prediction(committee=str(cand).strip(" .,;:|"))

        # Last resort: one LM call.
        out = self.fallback(email_body=text)
        guess = str(getattr(out, "committee", "") or "").strip()
        guess = re.sub(
            r"^(?:paid\s+for\s+(?:and\s+\w+\s+)?by\s*[:,-]?\s*)", "", guess, flags=re.IGNORECASE
        ).strip()
        guess = guess.strip(" .,;:|\"'“”")
        if not guess and looks_valid(chosen):
            guess = fix_leading_the(chosen, norm).strip(" .,;:|")
        return dspy.Prediction(committee=guess)
